selector_to_html = {"a[href=\"configure-backend-selection.html#user-specified-configuration-file-yaml\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">User-specified configuration file (YAML)<a class=\"headerlink\" href=\"#user-specified-configuration-file-yaml\" title=\"Link to this heading\">#</a></h2><p>Set the <code class=\"docutils literal notranslate\"><span class=\"pre\">VLLM_FL_CONFIG</span></code> environment variable to specify a YAML configuration file that completely overrides all other settings:</p>", "a[href=\"configure-backend-selection.html#environment-variables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment variables<a class=\"headerlink\" href=\"#environment-variables\" title=\"Link to this heading\">#</a></h2><p>Environment variables can override specific items from platform config. If not set, values from platform config file are used.</p>", "a[href=\"configure-backend-selection.html#operator-list\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Operator List<a class=\"headerlink\" href=\"#operator-list\" title=\"Link to this heading\">#</a></h2><p>This reference lists all operators supported by vllm-plugin-FL and their backend availability.</p>", "a[href=\"#operator-dispatch-user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Operator dispatch user guide<a class=\"headerlink\" href=\"#operator-dispatch-user-guide\" title=\"Link to this heading\">#</a></h1><p>This guide describes how to use an operator dispatch system that selects between FlagGems, vendor-specific, and PyTorch reference implementations. The selection follows a priority hierarchy, from highest to lowest:</p>", "a[href=\"configure-backend-selection.html#platform-specific-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Platform-specific configuration<a class=\"headerlink\" href=\"#platform-specific-configuration\" title=\"Link to this heading\">#</a></h2><p>The system detects the hardware platform from the vLLM platform\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">vendor_name</span></code> and loads the matching configuration file from the <code class=\"docutils literal notranslate\"><span class=\"pre\">config/</span></code> directory. Each platform config sets the preferred backend, the per-operator backend order, and the FlagGems/OOT blacklists.</p>", "a[href=\"add-ops-and-vendors.html#add-new-operators\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Add new operators<a class=\"headerlink\" href=\"#add-new-operators\" title=\"Link to this heading\">#</a></h2><p>When adding a new operator, modify these files:</p>", "a[href=\"add-ops-and-vendors.html#multi-process-safety\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-process safety<a class=\"headerlink\" href=\"#multi-process-safety\" title=\"Link to this heading\">#</a></h2><p>OpManager supports multi-process environments:</p>", "a[href=\"quick-start.html#use-the-manager\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Use the Manager<a class=\"headerlink\" href=\"#use-the-manager\" title=\"Link to this heading\">#</a></h2><p>For API explanations, see <a class=\"reference internal\" href=\"../reference/dispatch-api-reference.html\"><span class=\"std std-doc\">Dispatch API Reference</span></a>.</p>", "a[href=\"quick-start.html#basic-usage\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Basic usage<a class=\"headerlink\" href=\"#basic-usage\" title=\"Link to this heading\">#</a></h2>", "a[href=\"configure-backend-selection.html#configuration-priority\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Configuration priority<a class=\"headerlink\" href=\"#configuration-priority\" title=\"Link to this heading\">#</a></h2><p>The dispatch system applies configuration in the following order:</p>", "a[href=\"add-ops-and-vendors.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Add new operators and vendor backends<a class=\"headerlink\" href=\"#add-new-operators-and-vendor-backends\" title=\"Link to this heading\">#</a></h1><h2>Add new operators<a class=\"headerlink\" href=\"#add-new-operators\" title=\"Link to this heading\">#</a></h2><p>When adding a new operator, modify these files:</p>", "a[href=\"configure-policy.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Policy context management<a class=\"headerlink\" href=\"#policy-context-management\" title=\"Link to this heading\">#</a></h1><p>Supports temporary policy override in code:</p>", "a[href=\"configure-backend-selection.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Configure backend selection<a class=\"headerlink\" href=\"#configure-backend-selection\" title=\"Link to this heading\">#</a></h1><p>The dispatch system supports multiple ways to configure backend selection:</p>", "a[href=\"quick-start.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h1><h2>Basic usage<a class=\"headerlink\" href=\"#basic-usage\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
